from scipy.optimize import minimize_scalar
D=json.load(open('/app/data/calibration.json'))

def levels(theta,q,r,M=12,Ns=512):
 ph=2*np.pi*np.arange(Ns)/Ns
 # construct exact frame based existing
 I=np.eye(4); X=np.array([[0,1],[1,0]],complex); Z=np.diag([1.,-1.]);
 g=np.kron(I[:2,:2],X); j=np.kron(np.cos(theta)*Z+np.sin(theta)*X,Z)
 cs=np.cos(q*ph/2)[:,None,None]; ss=np.sin(q*ph/2)[:,None,None]
 first=cs*I-1j*ss*g
 cs2=np.cos(r*ph/2)[:,None,None]; ss2=np.sin(r*ph/2)[:,None,None]
 second=cs2*I-1j*ss2*j
 u=first@second
 der=(-1j*q/2*g)@u+first@((-1j*r/2*j)@second)
 w=u[:,:,2:]
 d=der[:,:,2:]
 A=np.einsum('nka,nkb->nab',d.conj(),d)/Ns
 B=np.einsum('nka,nkb->nab',d.conj(),w)/Ns
 C=np.einsum('nka,nkb->nab',w.conj(),d)/Ns
 # fft over n axis
 Ah=np.fft.fft(A,axis=0)/Ns; Bh=np.fft.fft(B,axis=0)/Ns; Ch=np.fft.fft(C,axis=0)/Ns
 ns=np.arange(-M,M+1); shift=((q+r)%2)/2; ks=ns-shift
 dim=2*len(ks); H=np.zeros((dim,dim),complex)
 for ii,k in enumerate(ks):
  for jj,l in enumerate(ks):
   if ii==jj: H[2*ii:2*ii+2,2*jj:2*jj+2]+=k*l*np.eye(2)
   m=int(round(k-l))%Ns
   H[2*ii:2*ii+2,2*jj:2*jj+2]+=Ah[m]+1j*l*Bh[m]-1j*k*Ch[m]
